select * 
from customer_behavior..customer_shopping_behavior 


-- Q1 What is the total revenue generated by the male vs female customers

select gender,sum(purchase_amount) [revenue]
from customer_behavior..customer_shopping_behavior
group by gender

-- Q2 Which customer used a discount but still spent more than average purchase amount?

select customer_id,discount_applied,purchase_amount
from customer_shopping_behavior
where discount_applied = 'Yes' and purchase_amount > (

select AVG(purchase_amount)
from customer_shopping_behavior
)

-- Q3 which are the top 5 products with the highest average review rating?

select * from(
select item_purchased,AVG(review_rating) [Average Review Rating],
DENSE_RANK () over (order by AVG(review_rating) desc) rnk
from customer_shopping_behavior
group by item_purchased) x
where rnk <=5

-- Q4 Compare the average Purchase Amounts between Standard and Express Shipping

select shipping_type,AVG(purchase_amount)[Average Purchase Amount S/E]
from customer_shopping_behavior
where shipping_type In ('Standard','Express')
group by shipping_type

-- Q5 Do subscribed customers spend more? Compare average spend and total revenue between subscribers and nonsubscriber.

select subscription_status,
COUNT(customer_id)[Total Customer],
AVG(purchase_amount)[Average Spend],
sum(purchase_amount)[Total Revenue]
from customer_shopping_behavior
group by subscription_status
order by [Average Spend],[Total Revenue] desc

-- Q6 Which 5 products have the highest percentage of purchases with discount applied?

select top 10 item_purchased,
ROUND(100*sum(case when discount_applied = 'Yes' then 1 else 0 end)/count(*),2) as discount_rate
from customer_shopping_behavior
group by item_purchased
order by discount_rate desc

-- Q7 segment customer into New, Returning, and Loyal based on their 
-- total number of previous purchases, and show the count of each segment.

with customer_type as(
select customer_id,previous_purchases,
CASE
	when previous_purchases = 1 then 'New'
	when previous_purchases between 2 and 10 then 'Returning'
	else 'Loyal'
	End as customer_segment
from customer_shopping_behavior
)

select customer_segment,count(*) [Number of Customers]
from customer_type
group by customer_segment


-- Q8 What are the top 3 Purchased Products within each cateogry

select * from(
select item_purchased,category,count(customer_id) [Total Purchases],
ROW_NUMBER () over (partition by category order by count(customer_id) desc ) rnk
from customer_shopping_behavior
group by item_purchased,category) x
where rnk<=3

-- Q9 Are Customer who are repeat buyers  (more than 5 previous purchase) also likely to subscribe?

select subscription_status, count(customer_id) as repeat_buyers
from customer_shopping_behavior
where previous_purchases > 5
group by subscription_status


-- Q10 what is the revenue contribution by each age_group?

select age_group,SUM(purchase_amount)[Total Revenue]
FROM customer_shopping_behavior
group by age_group


